({ appealReady(line) {
  const l = line && typeof line === "object" ? line : {};
  if (l.carc !== "CO-50") {
    return { ready: true, missing: [] };
  }
  const missing = [];
  const note = typeof l.noteRef === "string" ? l.noteRef : "";
  if (!/^DOC-\d{3}$/.test(note)) {
    missing.push("clinical-note reference");
  }
  const fd = typeof l.filingDeadline === "string" ? l.filingDeadline : "";
  let validDate = false;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(fd);
  if (m) {
    const y = Number(m[1]);
    const mo = Number(m[2]);
    const d = Number(m[3]);
    const dt = new Date(Date.UTC(y, mo - 1, d));
    validDate = dt.getUTCFullYear() === y && dt.getUTCMonth() === mo - 1 && dt.getUTCDate() === d;
  }
  if (!validDate) {
    missing.push("filing deadline");
  }
  return { ready: missing.length === 0, missing };
} })

