unitScript:
test("CO-50 with note DOC-123 and deadline 2024-05-30 (DOS 2024-03-01 plus 90 days) is ready", function() {
  assert.deepEqual(code.appealReady({ carc: "CO-50", noteRef: "DOC-123", filingDeadline: "2024-05-30" }), { ready: true, missing: [] });
});
test("CO-50 with a deadline but no note is blocked and names only the clinical-note reference", function() {
  assert.deepEqual(code.appealReady({ carc: "CO-50", noteRef: "", filingDeadline: "2024-05-30" }), { ready: false, missing: ["clinical-note reference"] });
});
test("CO-50 with a note but no deadline is blocked and names only the filing deadline", function() {
  assert.deepEqual(code.appealReady({ carc: "CO-50", noteRef: "DOC-123", filingDeadline: "" }), { ready: false, missing: ["filing deadline"] });
});
test("CO-50 with blank note and no deadline names both, even when the user is a supervisor or admin", function() {
  var expected = { ready: false, missing: ["clinical-note reference", "filing deadline"] };
  assert.deepEqual(code.appealReady({ carc: "CO-50", noteRef: "", filingDeadline: "", role: "supervisor" }), expected);
  assert.deepEqual(code.appealReady({ carc: "CO-50", noteRef: "", filingDeadline: "", role: "admin" }), expected);
});
test("CO-50 note not in DOC plus exactly three digits form, or an impossible date, counts as missing", function() {
  assert.deepEqual(code.appealReady({ carc: "CO-50", noteRef: "DOC-12", filingDeadline: "2024-05-30" }).missing, ["clinical-note reference"]);
  assert.deepEqual(code.appealReady({ carc: "CO-50", noteRef: "DOC-1234", filingDeadline: "2024-05-30" }).missing, ["clinical-note reference"]);
  assert.deepEqual(code.appealReady({ carc: "CO-50", noteRef: "DOC-123", filingDeadline: "2024-02-30" }).missing, ["filing deadline"]);
});
test("a non-CO-50 denial with no note and no deadline is not blocked by the gate", function() {
  assert.deepEqual(code.appealReady({ carc: "CO-97", noteRef: "", filingDeadline: "" }), { ready: true, missing: [] });
});

testScript:
test("non CO-50 denial with empty note and empty deadline is not blocked by this gate", function() {
  var result = code.appealReady({ carc: "CO-45", noteRef: "", filingDeadline: "" });
  assert.equal(result.ready, true);
  assert.deepEqual(result.missing, []);
});
test("CO-50 is ready when note DOC-123 and filing deadline 2024-05-30 are both present", function() {
  var result = code.appealReady({ carc: "CO-50", noteRef: "DOC-123", filingDeadline: "2024-05-30" });
  assert.equal(result.ready, true);
  assert.deepEqual(result.missing, []);
});
test("filing deadline 2024-05-30 is date of service 2024-03-01 plus 90 days and a missing date of service counts as a missing deadline", function() {
  var present = code.appealReady({ carc: "CO-50", noteRef: "DOC-123", filingDeadline: "2024-05-30" });
  var absent = code.appealReady({ carc: "CO-50", noteRef: "DOC-123", filingDeadline: "" });
  assert.equal(present.ready, true);
  assert.deepEqual(present.missing, []);
  assert.equal(absent.ready, false);
  assert.deepEqual(absent.missing, ["filing deadline"]);
});
test("CO-50 with an empty clinical note and a filing deadline names only the clinical-note reference", function() {
  var result = code.appealReady({ carc: "CO-50", noteRef: "", filingDeadline: "2024-05-30" });
  assert.equal(result.ready, false);
  assert.deepEqual(result.missing, ["clinical-note reference"]);
});
test("CO-50 with note DOC-123 and an empty filing deadline names only the filing deadline", function() {
  var result = code.appealReady({ carc: "CO-50", noteRef: "DOC-123", filingDeadline: "" });
  assert.equal(result.ready, false);
  assert.deepEqual(result.missing, ["filing deadline"]);
});
test("CO-50 with empty note and empty filing deadline names both missing items", function() {
  var result = code.appealReady({ carc: "CO-50", noteRef: "", filingDeadline: "" });
  assert.equal(result.ready, false);
  assert.deepEqual(result.missing, ["clinical-note reference", "filing deadline"]);
});
test("CO-50 treats note DOC-12 as a missing clinical-note reference because it is not DOC plus three digits", function() {
  var result = code.appealReady({ carc: "CO-50", noteRef: "DOC-12", filingDeadline: "2024-05-30" });
  assert.equal(result.ready, false);
  assert.deepEqual(result.missing, ["clinical-note reference"]);
});
test("a supervisor or admin cannot override a blocked CO-50 denial", function() {
  var supervisor = code.appealReady({ carc: "CO-50", noteRef: "", filingDeadline: "", role: "supervisor" });
  var admin = code.appealReady({ carc: "CO-50", noteRef: "", filingDeadline: "", role: "admin" });
  assert.equal(supervisor.ready, false);
  assert.deepEqual(supervisor.missing, ["clinical-note reference", "filing deadline"]);
  assert.equal(admin.ready, false);
  assert.deepEqual(admin.missing, ["clinical-note reference", "filing deadline"]);
});

